<script setup lang="ts">
import { computed, onMounted, onUnmounted, reactive, ref, watch } from 'vue'
import { ArrowUpRight, Check, ImagePlus, NotebookPen, RefreshCw } from 'lucide-vue-next'
import DraftNotice from '../components/DraftNotice.vue'
import { useDraft } from '../drafts'
import { api, dateLabel, isArchived, messageOf, notify, projectName, taskStatuses, ui } from '../api'
import type { RecordEntry, Task, Today } from '../types'
const props=defineProps<{revision:number}>();const emit=defineEmits<{changed:[];full:[];record:[project:string]}>()
const data=ref<Today>(),error=ref(''),loading=ref(false),saving=ref(false),updating=ref(''),form=reactive({project_id:'',content:''}),draft=useDraft(()=> 'compact:record:new',form),saveError=ref('')
const taskCount=computed(()=>data.value?.tasks.length||0)
async function load(){loading.value=true;error.value='';try{data.value=await api<Today>('/api/today')}catch(e){error.value=messageOf(e)}finally{loading.value=false}}
async function save(){if(saving.value||!form.content.trim())return;saving.value=true;saveError.value='';try{const record=await api<RecordEntry>('/api/records',{method:'POST',body:JSON.stringify({project_id:form.project_id,type:'note',content:form.content,title:'',tags:[],attachments:[]})});draft.discard();form.content='';await draft.reset();notify(record.reminder_parse_hint?`记录已保存；${record.reminder_parse_hint}`:'记录已保存');emit('changed');await load()}catch(e){saveError.value=messageOf(e);draft.persist()}finally{saving.value=false}}
function key(event:KeyboardEvent){if(event.key==='Enter'&&!event.shiftKey&&!event.isComposing){event.preventDefault();void save()}}
async function complete(task:Task){if(updating.value||task.has_children||isArchived(task.project_id))return;updating.value=task.id;error.value='';try{await api(`/api/tasks/${task.id}`,{method:'PATCH',body:JSON.stringify({version:task.version,status:'done',progress:100})});notify('叶子任务已完成');emit('changed');await load()}catch(e){error.value=messageOf(e)+'；任务状态没有改动，请刷新后重试。'}finally{updating.value=''}}
let refreshTimer:ReturnType<typeof setInterval>|undefined
function onVisible(){if(document.visibilityState==='visible')void load()}
onMounted(()=>{void load();refreshTimer=setInterval(()=>{if(!loading.value)void load()},60_000);document.addEventListener('visibilitychange',onVisible)})
onUnmounted(()=>{clearInterval(refreshTimer);document.removeEventListener('visibilitychange',onVisible)})
watch(()=>props.revision,load);defineExpose({canLeave:draft.canLeave})
</script>
<template><div class="compact-workbench"><header class="compact-header"><div><strong>ProjNote</strong><span>{{data?.date||'今日工作'}}</span></div><button class="button subtle small" @click="emit('full')">完整工作台<ArrowUpRight :size="14"/></button></header><div v-if="error" class="error-banner" role="alert">{{error}}<button class="text-button" @click="load">刷新</button></div><section class="compact-capture"><div class="compact-section-heading"><h1><NotebookPen :size="17"/>随手记</h1><button class="text-button" :disabled="saving" @click="emit('record',form.project_id)"><ImagePlus :size="14"/>图片与更多选项</button></div><DraftNotice :value="draft.available.value" :values="draft.values.value" :error="draft.storageError.value" :recovery="draft.recovery.value" @select="draft.select" @restore="draft.restore" @force="draft.restoreForced" @cancel-recovery="draft.clearRecovery" @discard="draft.discardAvailable"/><form @submit.prevent="save"><label class="sr-only" for="compact-project">记录项目</label><select id="compact-project" v-model="form.project_id" :disabled="saving"><option value="">未归类</option><option v-for="p in ui.projects.filter(p=>p.status!=='archived')" :key="p.id" :value="p.id">{{p.name}}</option></select><label class="sr-only" for="compact-note">速记内容</label><textarea id="compact-note" v-model="form.content" :disabled="saving" autofocus rows="4" placeholder="记下刚发生的事…" @keydown="key"/><p v-if="saveError" class="form-error" role="alert">{{saveError}}</p><div class="compact-save-row"><span>Enter 保存 · Shift + Enter 换行</span><button class="button primary small" :disabled="saving||!form.content.trim()">{{saving?'保存中…':'保存记录'}}</button></div></form></section><section class="compact-tasks"><div class="compact-section-heading"><h2>今日任务 <span class="count">{{taskCount}}</span></h2><button class="icon-button" :disabled="loading" aria-label="刷新今日任务" @click="load"><RefreshCw :size="15"/></button></div><p v-if="loading&&!data" class="loading-message">正在读取…</p><p v-else-if="!data?.tasks.length" class="compact-empty">当前没有待办。打开完整工作台规划下一步。</p><ul v-else><li v-for="task in data.tasks" :key="task.id"><button v-if="!task.has_children" class="compact-complete" :disabled="!!updating||isArchived(task.project_id)" :aria-label="`完成叶子任务 ${task.name}`" @click="complete(task)"><Check v-if="updating===task.id" :size="13"/></button><span v-else class="compact-parent-mark" title="汇总任务，完成子任务后自动汇总">Σ</span><div><strong>{{task.name}}</strong><p>{{projectName(task.project_id)}} <span v-if="task.plan_end"> · {{dateLabel(task.plan_end)}} 截止</span></p></div><span class="badge" :class="task.status">{{taskStatuses[task.status]}}</span></li></ul><p class="input-hint">仅叶子任务提供完成按钮，汇总任务随子任务计算。</p></section></div></template>
